      dlyByDeb(keys.filter(k => !cur.includes(k))).forEach(k => { const lo = k.split("|")[0]; let i = -1; cur.forEach((c, j) => { if (c.split("|")[0] === lo) i = j; }); if (i < 0) cur.push(k); else cur.splice(i + 1, 0, k); });
